  (exists jpad jseq, rw_cells bsegs m1 (v_FRB P) (sqs_frame P OEND c0 c8 c152 c160 c168 c200 c208 c216 LP jseq) /\
                     rw_cells bsegs m1 (v_FF P) (sqs_ffr P cw bc ptr sLL sOF sML p0 p1 p2 jpad)) /\
  bytes_at bsegs m1 (v_LLT P) (map (Z_to_bv 8) (seq_table_bytes (v_tLL P))) /\
